                    for j in &sset {
                        self.objs[si].hidden.insert(*j);
                    }
                }
                push(
                    self,
                    Fx::Morph {
                        dst: id,
                        set: dset,
                        src: src_prims,
                        pairs,
                        outs: Vec::new(),
                        ins,
                        copy: true,
