            id,
            kind,
            pts,
            color,
            width: o.width,
            dash,
            reveal: grow.clamp(0.0, 1.0),
        };
        match &o.content {
            Content::Point(_) => vec![one(SpatialKind::Point, pts, o.id.clone(), false)],
            Content::Line { arrow, .. } => {
                let kind = if *arrow {
                    SpatialKind::Arrow
                } else {
                    SpatialKind::Line
                };
                vec![one(kind, pts, o.id.clone(), o.dash)]
            }
            Content::Polyline { closed, .. } => {
                let mut pts = pts;
                if *closed && !pts.is_empty() {
                    pts.push(pts[0]);
