impl Anim {
    /// Progress at `now`, 0..1.
    fn p(&self, now: f64) -> f64 {
        if self.dur <= 0.0 {
            1.0
        } else {
            ((now - self.t0) / self.dur).clamp(0.0, 1.0)
        }
    }
}

/// A stage deck at one step, with its running animations.
pub struct Stage {
