        "Pi" => 'Π',
        "Sigma" => 'Σ',
        "Upsilon" => 'Υ',
        "Phi" => 'Φ',
        "Psi" => 'Ψ',
        "Omega" => 'Ω',
        "partial" => '∂',
        "nabla" => '∇',
        "infty" => '∞',
        "cdot" => '⋅',
