        "le" | "leq" => '≤',
        "ge" | "geq" => '≥',
        "to" | "rightarrow" => '→',
        "leftarrow" | "gets" => '←',
        "Rightarrow" => '⇒',
        "Leftarrow" => '⇐',
        "Leftrightarrow" => '⇔',
        "implies" | "Longrightarrow" => '⟹',
