use super::font::{BOLD, Construction, FontId, Fonts, MATH, Part, TEXT};
use std::collections::HashMap;

/// A colour as red, green, blue and alpha in 0..1.
pub type Rgba = [f32; 4];

/// A drawable piece of a formula, em units, y down from the baseline.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Shape {
    Glyph {
        font: FontId,
        gid: u16,
        size: f32,
    },
    Rect {
        w: f32,
        h: f32,
        radius: f32,
        fill: f32,
        stroke: f32,
    },
    Stroke {
        dx: f32,
        dy: f32,
        width: f32,
    },
    Image {
        index: u16,
        w: f32,
        h: f32,
    },
}

/// A shape at its position; `x, y` is the glyph pen point or the rect's top-left corner.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Prim {
    pub shape: Shape,
    pub x: f32,
    pub y: f32,
    pub color: Option<Rgba>,
    pub part: Option<u16>,
}

/// A laid-out formula or paragraph, em units.
#[derive(Clone, Debug, Default)]
pub struct Expr {
    pub prims: Vec<Prim>,
    pub parts: Vec<String>,
    pub w: f32,
    pub h: f32,
    pub d: f32,
    pub align: Option<f32>,
    pub unknown: Vec<String>,
}

impl Shape {
    /// What morph matching compares: equal glyphs, or two rules.
    pub fn ident(&self) -> u64 {
        match *self {
            Shape::Glyph { font, gid, .. } => ((font as u64) << 16) | gid as u64,
            Shape::Rect { .. } => 1 << 40,
            Shape::Stroke { .. } => 2 << 40,
            Shape::Image { index, .. } => (3 << 40) | index as u64,
        }
    }

    /// The shape `k` times larger, keeping a rect's corner radius and outline width.
    pub fn resized(self, k: f32) -> Shape {
        match self {
            Shape::Glyph { font, gid, size } => Shape::Glyph {
                font,
                gid,
                size: size * k,
            },
            Shape::Rect {
                w,
                h,
                radius,
                fill,
                stroke,
            } => Shape::Rect {
                w: w * k,
                h: h * k,
                radius,
                fill,
                stroke,
            },
            Shape::Stroke { dx, dy, width } => Shape::Stroke {
                dx: dx * k,
                dy: dy * k,
                width: width * k,
            },
            Shape::Image { index, w, h } => Shape::Image {
                index,
                w: w * k,
                h: h * k,
            },
        }
    }
}

impl Expr {
    /// Prims tagged with the part whose key is `key`.
    pub fn part(&self, key: &str) -> Vec<usize> {
        let ids: Vec<u16> = self
            .parts
            .iter()
            .enumerate()
            .filter(|(_, k)| k.as_str() == key)
            .map(|(i, _)| i as u16)
            .collect();
        self.prims
            .iter()
            .enumerate()
            .filter(|(_, p)| p.part.is_some_and(|id| ids.contains(&id)))
            .map(|(i, _)| i)
            .collect()
    }
}

/// TeX's atom classes, which decide the space between neighbours.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Class {
    Ord,
    Op,
    Bin,
    Rel,
    Open,
    Close,
    Punct,
    Inner,
}

/// The math alphabet a letter is drawn from.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Variant {
    Italic,
    Upright,
    Bold,
    BoldItalic,
}

/// TeX's math style.
#[derive(Clone, Copy, Debug)]
struct Style {
    level: u8,     // 0 display, 1 text, 2 script, 3 scriptscript.
    cramped: bool, // Superscripts sit lower.
}

impl Style {
    const DISPLAY: Style = Style {
        level: 0,
        cramped: false,
    };
    const TEXT: Style = Style {
        level: 1,
        cramped: false,
    };
    fn scale(self, f: &Fonts) -> f32 {
        match self.level {
            0 | 1 => 1.0,
            2 => f.c.script,
            _ => f.c.script_script,
        }
    }
    fn sup(self) -> Style {
        Style {
            level: if self.level < 2 { 2 } else { 3 },
            cramped: self.cramped,
        }
    }
    fn sub(self) -> Style {
        Style {
            cramped: true,
            ..self.sup()
        }
    }
    fn num(self) -> Style {
        Style {
            level: (self.level + 1).clamp(1, 3),
            cramped: self.cramped,
        }
    }
    fn den(self) -> Style {
        Style {
            cramped: true,
            ..self.num()
        }
    }
    fn cramp(self) -> Style {
        Style {
            cramped: true,
            ..self
        }
    }
    fn script(self) -> bool {
        self.level >= 2
    }
}

/// A parsed piece of a formula.
#[derive(Clone, Debug)]
enum Node {
    Char(char, Variant),
    Group(Vec<Node>),
    Scripts {
        base: Box<Node>,
        sup: Option<Box<Node>>,
        sub: Option<Box<Node>>,
    },
    Frac {
        num: Vec<Node>,
        den: Vec<Node>,
        style: Option<Style>,
    },
    Sqrt(Vec<Node>),
    Delim {
        left: Option<char>,
        right: Option<char>,
        body: Vec<Node>,
    },
    Big(char, f32, Class),
    Text(String, bool),
    Space(f32),
    OpGlyph(char, bool),
    OpWord(String, bool),
    Accent(char, Vec<Node>, bool),
    Overline(Vec<Node>),
    Underline(Vec<Node>),
    Brace {
        body: Vec<Node>,
        label: Option<Vec<Node>>,
        under: bool,
    },
    Cancel(Vec<Node>),
    XArrow(Vec<Node>, char),
    Phantom(Vec<Node>),
    Boxed(Vec<Node>),
    StyleSet(Style),
    ColorPush(Rgba),
    ColorPop,
    PartPush(u16),
    PartPop,
    Align,
}

/// A lexed TeX token.
#[derive(Clone, Debug, PartialEq)]
enum Tok {
    Cmd(String),
    Ch(char),
    Open,
    Close,
    Sup,
    Sub,
    PartOpen,
    PartClose,
    Amp,
    Raw(String),
}

/// Commands whose braced argument is kept as raw text.
const RAW: [&str; 5] = ["text", "textrm", "textbf", "mbox", "operatorname"];

/// Split TeX source into tokens.
fn lex(src: &str) -> Vec<Tok> {
    let chars: Vec<char> = src.chars().collect();
    let mut out = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        match c {
            '\\' => {
                i += 1;
                if i >= chars.len() {
                    break;
                }
                if chars[i].is_ascii_alphabetic() {
                    let start = i;
                    while i < chars.len() && chars[i].is_ascii_alphabetic() {
                        i += 1;
                    }
                    let name: String = chars[start..i].iter().collect();
                    let raw = RAW.contains(&name.as_str());
                    out.push(Tok::Cmd(name));
                    if raw {
                        let mut j = i;
                        while j < chars.len() && chars[j] == ' ' {
                            j += 1;
                        }
                        if chars.get(j) == Some(&'{') {
                            let mut depth = 0;
                            let mut k = j;
                            while k < chars.len() {
                                if chars[k] == '{' {
                                    depth += 1;
                                } else if chars[k] == '}' {
                                    depth -= 1;
                                    if depth == 0 {
                                        break;
                                    }
                                }
                                k += 1;
                            }
                            out.push(Tok::Raw(chars[j + 1..k.min(chars.len())].iter().collect()));
                            i = k + 1;
                        }
                    }
                    continue;
                }
                out.push(Tok::Cmd(chars[i].to_string()));
            }
            '{' if chars.get(i + 1) == Some(&'{') => {
                out.push(Tok::PartOpen);
                i += 1;
            }
            '}' if chars.get(i + 1) == Some(&'}') && part_depth(&out) > 0 => {
                out.push(Tok::PartClose);
                i += 1;
            }
            '{' => out.push(Tok::Open),
            '}' => out.push(Tok::Close),
            '^' => out.push(Tok::Sup),
            '_' => out.push(Tok::Sub),
            '&' => out.push(Tok::Amp),
            '%' => {
                while i < chars.len() && chars[i] != '\n' {
                    i += 1;
                }
            }
            c if c.is_whitespace() => {}
            c => out.push(Tok::Ch(c)),
        }
        i += 1;
    }
    out
}

/// Open `{{` parts not yet closed, so `}}` only closes a part when one is open.
fn part_depth(toks: &[Tok]) -> i32 {
    let mut depth = 0;
    let mut braces: Vec<bool> = Vec::new();
    for t in toks {
        match t {
            Tok::PartOpen => {
                depth += 1;
                braces.push(true);
            }
            Tok::PartClose => {
                depth -= 1;
                braces.pop();
            }
            Tok::Open => braces.push(false),
            Tok::Close => {
                braces.pop();
            }
            _ => {}
        }
    }
    // a `}}` right after an ordinary open brace inside the part closes that brace first
    if braces.last() == Some(&false) {
        0
    } else {
        depth
    }
}

/// Reads tokens into nodes, collecting part keys and unknown commands.
struct Parser<'a> {
    toks: Vec<Tok>,
    pos: usize,
    palette: &'a HashMap<String, Rgba>,
    parts: Vec<String>,
    unknown: Vec<String>,
}

